import Foundation

/// Where the games' art sits in `Assets/Games/games.png`, read from
/// `games.json` (both generated by Tools/generate_sprites.py).
public struct GameSheet: Codable, Equatable, Sendable {
    /// A rectangle in the sheet (top-left origin) with `frames` frames of
    /// `w`×`h` side by side, starting at `x`, `y`.
    public struct Item: Codable, Equatable, Sendable {
        public let x: Int
        public let y: Int
        public let w: Int
        public let h: Int
        public let frames: Int

        public init(x: Int, y: Int, w: Int, h: Int, frames: Int = 1) {
            self.x = x
            self.y = y
            self.w = w
            self.h = h
            self.frames = frames
        }

        /// Where frame `index` is (wrapping around).
        public func frame(_ index: Int) -> (x: Int, y: Int) {
            let n = max(frames, 1)
            return (x + ((index % n) + n) % n * w, y)
        }
    }

    /// The window around the playfield.
    public struct Chrome: Codable, Equatable, Sendable {
        /// The whole frame, the same size as the window in art pixels; the
        /// playfield's hole is transparent.
        public let frame: Item
        /// Where the playfield sits inside the frame.
        public let playfieldX: Int
        public let playfieldY: Int
        /// The title's top-left corner inside the frame.
        public let titleX: Int
        public let titleY: Int
        /// The close button: frame 0 normal, frame 1 under the pointer.
        public let close: Item
        public let closeX: Int
        public let closeY: Int
    }

    public let chrome: Chrome
    /// Game art by "<game id>.<name>", e.g. "shellCatch.pibbo".
    public let items: [String: Item]

    public init(json: Data) throws {
        self = try JSONDecoder().decode(GameSheet.self, from: json)
    }

    /// The sheet item a game's sprite or background names.
    public func item(game: String, name: String) -> Item? {
        items["\(game).\(name)"]
    }
}
